CREATE TABLE customers(id varchar(100) PRIMARY KEY,display_name varchar(255) NOT NULL,status varchar(20) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(100) PRIMARY KEY,customer_id varchar(100) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(20) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')),incoming_allowed boolean NOT NULL DEFAULT true,outgoing_allowed boolean NOT NULL DEFAULT true,transfer_limit numeric(19,3) NOT NULL DEFAULT 10000 CHECK(transfer_limit>0),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,principal varchar(200) NOT NULL,can_debit boolean NOT NULL DEFAULT false,can_view boolean NOT NULL DEFAULT false,PRIMARY KEY(account_id,principal));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(100) NOT NULL,to_account_id varchar(100) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000) NOT NULL,payload_fingerprint char(64) NOT NULL,status varchar(20) NOT NULL CHECK(status IN ('PROCESSING','COMPLETED','REJECTED')),rejection_code varchar(60),rejection_http int,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(200) NOT NULL,correlation_id uuid NOT NULL);
CREATE INDEX payments_source_time ON payments(from_account_id,created_at);
CREATE INDEX payments_destination_time ON payments(to_account_id,created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(6) NOT NULL CHECK(entry_type IN ('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id,id);
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial records are immutable'; END $$;
CREATE TRIGGER ledger_append_only BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE FUNCTION immutable_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status<>'PROCESSING' THEN RAISE EXCEPTION 'Final payment is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_payment();
CREATE FUNCTION verify_payment() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p payments%ROWTYPE; n integer; total numeric; BEGIN SELECT * INTO p FROM payments WHERE payment_id=NEW.payment_id; SELECT count(*),coalesce(sum(signed_amount),0) INTO n,total FROM ledger_entries WHERE payment_id=p.payment_id; IF p.status='PROCESSING' OR (p.status='COMPLETED' AND (n<>2 OR total<>0 OR NOT EXISTS(SELECT 1 FROM ledger_entries WHERE payment_id=p.payment_id AND entry_type='DEBIT' AND account_id=p.from_account_id AND signed_amount=-p.amount) OR NOT EXISTS(SELECT 1 FROM ledger_entries WHERE payment_id=p.payment_id AND entry_type='CREDIT' AND account_id=p.to_account_id AND signed_amount=p.amount))) OR (p.status='REJECTED' AND n<>0) THEN RAISE EXCEPTION 'Payment ledger invariant violated'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER payment_balanced AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_payment();
CREATE CONSTRAINT TRIGGER ledger_balanced AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_payment();
